package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public class MappingActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);String id=getIntent().getStringExtra("id");DocumentStore.Item item=DocumentStore.find(this,id);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Correspondance à la norme",27,true));if(item==null){r.addView(Ui.text(this,"Document introuvable.",15,false));setContentView(Ui.wrap(this,r));return;}try{List<DataNormalizer.ColumnMapping> maps=DocumentStore.readMappings(this,item);if(maps.isEmpty()){r.addView(Ui.text(this,"Aucun audit détaillé disponible. Réimportez le fichier pour générer la correspondance champ par champ.",14,false));}else{int ok=0,check=0,out=0;for(DataNormalizer.ColumnMapping m:maps){if("CONFORME".equals(m.status))ok++;else if("À VALIDER".equals(m.status))check++;else out++;}r.addView(Ui.text(this,"Conformes : "+ok+" · À valider : "+check+" · Hors profil : "+out,15,true));for(DataNormalizer.ColumnMapping m:maps){LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,m.status,16,true));p.addView(Ui.text(this,"Origine : "+m.sourceHeader+"\nNormalisé : "+m.normalizedHeader+"\nCible : "+(m.targetField.isEmpty()?"—":m.targetField)+"\nAvant : "+m.sampleBefore+"\nAprès : "+m.sampleAfter+"\nJustification : "+m.reason,14,false));r.addView(p);}Button share=Ui.primary(this,"Exporter / partager l’audit CSV");share.setOnClickListener(v->share(maps,item));r.addView(share);}}catch(Exception e){r.addView(Ui.text(this,"Erreur de lecture : "+e.getMessage(),14,false));}r.addView(Ui.text(this,"Cet audit facilite la validation humaine et documente la mise à niveau. Il ne constitue pas une certification officielle.",12,false));setContentView(Ui.wrap(this,r));}private void share(List<DataNormalizer.ColumnMapping> maps,DocumentStore.Item item){StringBuilder b=new StringBuilder("source,normalise,cible,avant,apres,statut,justification\n");for(DataNormalizer.ColumnMapping m:maps)b.append(q(m.sourceHeader)).append(',').append(q(m.normalizedHeader)).append(',').append(q(m.targetField)).append(',').append(q(m.sampleBefore)).append(',').append(q(m.sampleAfter)).append(',').append(q(m.status)).append(',').append(q(m.reason)).append('\n');Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/csv");i.putExtra(Intent.EXTRA_SUBJECT,"Audit de standardisation - "+item.name);i.putExtra(Intent.EXTRA_TEXT,b.toString());startActivity(Intent.createChooser(i,"Partager l’audit"));}private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}}
